        async fn insert_organization(
            &self,
            input: &CreateOrganizationInput,
        ) -> Result<OrganizationRecord, CreateOrganizationStoreError> {
            let mut organizations = self.organizations.lock().map_err(|error| {
                CreateOrganizationStoreError::Storage(StorageError::unavailable(error.to_string()))
            })?;
            // Check for uniqueness.
            if organizations
                .values()
                .any(|org| !org.deleted && org.name.eq_ignore_ascii_case(&input.name))
            {
                return Err(CreateOrganizationStoreError::AlreadyExists);
            }
            let now = OffsetDateTime::now_utc();
            let org = OrganizationRecord {
                id: Uuid::new_v4(),
                name: input.name.clone(),
                display_name: input.display_name.clone(),
                description: input.description.clone(),
                icon: input.icon.clone(),
                created_at: now,
                updated_at: now,
                is_default: false,
                deleted: false,
                workspace_sharing_mode: WorkspaceSharingMode::default(),
            };
            organizations.insert(org.id, org.clone());

            // Auto-create the "Everyone" group (id == org.id), matching the
            // real database trigger / migration behaviour.
            if let Ok(mut groups) = self.groups.lock() {
                groups.insert(
                    org.id,
                    GroupRecord {
                        id: org.id,
                        name: "Everyone".to_owned(),
                        display_name: String::new(),
                        organization_id: org.id,
                        avatar_url: String::new(),
                        quota_allowance: 0,
                        source: "user".to_owned(),
                        created_at: now,
                    },
                );
            }

            Ok(org)
        }

        async fn update_organization(
            &self,
            input: &UpdateOrganizationInput,
        ) -> Result<OrganizationRecord, UpdateOrganizationStoreError> {
            let mut organizations = self.organizations.lock().map_err(|error| {
                UpdateOrganizationStoreError::Storage(StorageError::unavailable(error.to_string()))
            })?;
            // Check uniqueness for name collision with a different org.
            if organizations.values().any(|org| {
                !org.deleted && org.id != input.id && org.name.eq_ignore_ascii_case(&input.name)
            }) {
                return Err(UpdateOrganizationStoreError::AlreadyExists);
            }
            let org = organizations.get_mut(&input.id).ok_or_else(|| {
                UpdateOrganizationStoreError::Storage(StorageError::not_found(
                    "Organization not found.",
                ))
            })?;
            org.name = input.name.clone();
            org.display_name = input.display_name.clone();
            org.description = input.description.clone();
            org.icon = input.icon.clone();
            org.updated_at = OffsetDateTime::now_utc();
            Ok(org.clone())
        }

        async fn soft_delete_organization(&self, id: Uuid) -> Result<bool, StorageError> {
            let mut organizations = self
                .organizations
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?;
            if let Some(org) = organizations.get_mut(&id) {
                if org.deleted {
                    return Ok(false);
                }
                org.deleted = true;
                Ok(true)
            } else {
                Ok(false)
            }
        }

        async fn get_organization_resource_counts(
            &self,
            id: Uuid,
        ) -> Result<OrgResourceCounts, StorageError> {
            let member_count = self
                .organization_members
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?
                .keys()
                .filter(|(org_id, _)| *org_id == id)
                .count() as u64;
            let group_count = self
                .groups
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?
                .values()
                .filter(|g| g.organization_id == id)
                .count() as u64;
            Ok(OrgResourceCounts {
                workspace_count: 0,
                template_count: 0,
                member_count,
                group_count,
                provisioner_key_count: 0,
            })
        }

        async fn get_organization_sharing_settings(
            &self,
            organization_id: Uuid,
        ) -> Result<Option<WorkspaceSharingMode>, StorageError> {
            let organizations = self
                .organizations
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?;
            let Some(org) = organizations.get(&organization_id) else {
                return Ok(None);
            };
            if org.deleted {
                return Ok(None);
            }
            let default_mode = org.workspace_sharing_mode;
            drop(organizations);
            let sharing = self
                .organization_sharing
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?;
            Ok(Some(
                sharing
                    .get(&organization_id)
                    .copied()
                    .unwrap_or(default_mode),
            ))
        }

        async fn update_organization_sharing_settings(
            &self,
            organization_id: Uuid,
            mode: WorkspaceSharingMode,
        ) -> Result<Option<WorkspaceSharingMode>, StorageError> {
            let mut organizations = self
                .organizations
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?;
            let Some(org) = organizations.get_mut(&organization_id) else {
                return Ok(None);
            };
            if org.deleted {
                return Ok(None);
            }
            org.updated_at = OffsetDateTime::now_utc();
            // Keep the OrganizationRecord in lock-step with the sharing map
            // so the denormalised record mirrors what the PostgresStore
            // returns after the same update.
            org.workspace_sharing_mode = mode;
            drop(organizations);
            let mut sharing = self
                .organization_sharing
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?;
            sharing.insert(organization_id, mode);
            Ok(Some(mode))
        }

