        async fn get_webpush_vapid_keys(
            &self,
        ) -> Result<Option<coder_core::api::VapidKeyPair>, StorageError> {
            let keys = self
                .vapid_keys
                .lock()
                .map_err(|error| StorageError::unavailable(error.to_string()))?
                .clone();
            // Mirror PostgresStore behavior: return None if either key is empty
            match keys {
                Some(ref kp) if !kp.public_key.is_empty() && !kp.private_key.is_empty() => Ok(keys),
                _ => Ok(None),
            }
        }

        async fn upsert_webpush_vapid_keys(
            &self,
            public_key: &str,
            private_key: &str,
        ) -> Result<(), StorageError> {
            *self
                .vapid_keys
                .lock()
                .map_err(|error: std::sync::PoisonError<_>| {
                    StorageError::unavailable(error.to_string())
                })? = Some(coder_core::api::VapidKeyPair {
                public_key: public_key.to_owned(),
                private_key: private_key.to_owned(),
            });
            Ok(())
        }
        // ----- Template Store Methods -----

        async fn list_templates(
            &self,
            filter: TemplateListFilter,
        ) -> Result<Vec<TemplateRecord>, StorageError> {
            let templates = self
                .templates
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            let mut results: Vec<TemplateRecord> = templates
                .values()
                .filter(|t| {
                    if !filter.deleted && t.deleted {
                        return false;
                    }
                    if let Some(ref org_id) = filter.organization_id {
                        if t.organization_id != *org_id {
                            return false;
                        }
                    }
                    if let Some(ref name) = filter.exact_name {
                        if t.name != *name {
                            return false;
                        }
                    }
                    if let Some(ref search) = filter.search {
                        let lower = search.to_lowercase();
                        if !t.name.to_lowercase().contains(&lower)
                            && !t.display_name.to_lowercase().contains(&lower)
                        {
                            return false;
                        }
                    }
                    true
                })
                .cloned()
                .collect();
            results.sort_by(|a, b| a.name.cmp(&b.name));
            Ok(results)
        }

