        async fn list_oauth2_provider_app_tokens_by_app_and_user(
            &self,
            app_id: Uuid,
            user_id: Uuid,
        ) -> Result<Vec<coder_core::identity::OAuth2ProviderAppTokenRecord>, StorageError> {
            // Collect secret IDs first, then drop the secrets lock before acquiring tokens lock
            let app_secret_ids: std::collections::HashSet<Uuid> = {
                let secrets = self
                    .oauth2_app_secrets
                    .lock()
                    .map_err(|e| StorageError::unavailable(e.to_string()))?;
                secrets
                    .values()
                    .filter(|s| s.app_id == app_id)
                    .map(|s| s.id)
                    .collect()
            };
            let tokens = self
                .oauth2_app_tokens
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            Ok(tokens
                .values()
                .filter(|t| t.user_id == user_id && app_secret_ids.contains(&t.app_secret_id))
                .cloned()
                .collect())
        }

        async fn delete_oauth2_provider_app_tokens_by_app_and_user(
            &self,
            app_id: Uuid,
            user_id: Uuid,
        ) -> Result<u64, StorageError> {
            // Collect secret IDs first, then drop the secrets lock before acquiring tokens lock
            let app_secret_ids: std::collections::HashSet<Uuid> = {
                let secrets = self
                    .oauth2_app_secrets
                    .lock()
                    .map_err(|e| StorageError::unavailable(e.to_string()))?;
                secrets
                    .values()
                    .filter(|s| s.app_id == app_id)
                    .map(|s| s.id)
                    .collect()
            };
            let mut tokens = self
                .oauth2_app_tokens
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            let before = tokens.len();
            tokens.retain(|_, t| {
                !(t.user_id == user_id && app_secret_ids.contains(&t.app_secret_id))
            });
            let after = tokens.len();
            Ok((before - after) as u64)
        }

        async fn list_workspaces(
            &self,
            filter: WorkspaceListFilter,
        ) -> Result<(Vec<WorkspaceRecord>, i64), StorageError> {
            // Pre-resolve owner_username -> owner_id so we can filter by username.
            let resolved_owner_id: Option<Uuid> = if filter.owner_id.is_some() {
                filter.owner_id
            } else if let Some(ref username) = filter.owner_username {
                let users = self
                    .users
                    .lock()
                    .map_err(|e| StorageError::unavailable(e.to_string()))?;
                users
                    .values()
                    .find(|u| u.username == *username)
                    .map(|u| u.id)
            } else {
                None
            };
            // Pre-resolve template_name -> template_id so we can filter by name.
            let resolved_template_name_id: Option<Uuid> =
                if let Some(ref tname) = filter.template_name {
                    let templates = self
                        .templates
                        .lock()
                        .map_err(|e| StorageError::unavailable(e.to_string()))?;
                    templates
                        .values()
                        .find(|t| t.name == *tname && !t.deleted)
                        .map(|t| t.id)
                } else {
                    None
                };
            let workspaces = self
                .workspaces
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            let mut rows: Vec<WorkspaceRecord> = workspaces
                .values()
                .filter(|w| !w.deleted)
                .filter(|w| {
                    if filter.owner_id.is_some() || filter.owner_username.is_some() {
                        resolved_owner_id.is_some_and(|owner_id| w.owner_id == owner_id)
                    } else {
                        true
                    }
                })
                .filter(|w| {
                    filter.name.as_ref().is_none_or(|n| {
                        let lower = n.to_lowercase();
                        w.name.to_lowercase().contains(&lower)
                    })
                })
                .filter(|w| {
                    filter
                        .organization_id
                        .is_none_or(|org_id| w.organization_id == org_id)
                })
                .filter(|w| {
                    filter.template_ids.is_empty() || filter.template_ids.contains(&w.template_id)
                })
                .filter(|w| {
                    // Filter by template_name: if set, only include matching template.
                    if filter.template_name.is_some() {
                        resolved_template_name_id.is_some_and(|tid| w.template_id == tid)
                    } else {
                        true
                    }
                })
                .filter(|w| {
                    filter.dormant.is_none_or(|d| {
                        if d {
                            w.dormant_at.is_some()
                        } else {
                            w.dormant_at.is_none()
                        }
                    })
                })
                .cloned()
                .collect();
            // Match PostgresStore: ORDER BY w.last_used_at DESC.
            rows.sort_by(|a, b| b.last_used_at.cmp(&a.last_used_at));
            let count = i64::try_from(rows.len()).unwrap_or(0);
            let offset = usize::try_from(filter.offset).unwrap_or(0);
            let limit = usize::try_from(filter.limit).unwrap_or(25);
            rows = rows.into_iter().skip(offset).take(limit).collect();
            Ok((rows, count))
        }

