        // -----------------------------------------------------------------
        // Notification Messages
        // -----------------------------------------------------------------

        async fn acquire_pending_notification_messages(
            &self,
            limit: u32,
            max_attempt_count: u32,
        ) -> Result<Vec<NotificationMessageRecord>, StorageError> {
            let messages = self
                .notification_messages
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            Ok(messages
                .iter()
                .filter(|m| {
                    m.status == NotificationMessageStatus::Pending
                        && (m.attempt_count as u32) < max_attempt_count
                })
                .take(limit as usize)
                .cloned()
                .collect())
        }

        async fn update_notification_message_status(
            &self,
            message_id: Uuid,
            status: NotificationMessageStatus,
        ) -> Result<bool, StorageError> {
            let mut messages = self
                .notification_messages
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            if let Some(msg) = messages.iter_mut().find(|m| m.id == message_id) {
                msg.status = status;
                msg.updated_at = OffsetDateTime::now_utc();
                Ok(true)
            } else {
                Ok(false)
            }
        }

        async fn increment_notification_message_attempt_count(
            &self,
            message_id: Uuid,
        ) -> Result<bool, StorageError> {
            let mut messages = self
                .notification_messages
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            if let Some(msg) = messages.iter_mut().find(|m| m.id == message_id) {
                msg.attempt_count += 1;
                msg.updated_at = OffsetDateTime::now_utc();
                Ok(true)
            } else {
                Ok(false)
            }
        }

        async fn bulk_mark_notification_messages_sent(
            &self,
            ids: &[Uuid],
        ) -> Result<u64, StorageError> {
            let mut messages = self
                .notification_messages
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            let now = OffsetDateTime::now_utc();
            let mut count = 0u64;
            for msg in messages.iter_mut() {
                if ids.contains(&msg.id) {
                    msg.status = NotificationMessageStatus::Sent;
                    msg.updated_at = now;
                    msg.attempt_count = msg.attempt_count.saturating_add(1);
                    count += 1;
                }
            }
            Ok(count)
        }

        async fn bulk_mark_notification_messages_failed(
            &self,
            ids: &[Uuid],
            statuses: &[NotificationMessageStatus],
            _status_reasons: &[String],
            max_attempts: u32,
            _retry_interval_secs: u32,
        ) -> Result<u64, StorageError> {
            let mut messages = self
                .notification_messages
                .lock()
                .map_err(|e| StorageError::unavailable(e.to_string()))?;
            let now = OffsetDateTime::now_utc();
            let mut count = 0u64;
            for (idx, id) in ids.iter().enumerate() {
                let Some(msg) = messages.iter_mut().find(|m| m.id == *id) else {
                    continue;
                };
                let next = msg.attempt_count.saturating_add(1);
                let status = statuses
                    .get(idx)
                    .copied()
                    .unwrap_or(NotificationMessageStatus::TemporaryFailure);
                msg.status = if (next as u32) >= max_attempts {
                    NotificationMessageStatus::PermanentFailure
                } else {
                    status
                };
                msg.attempt_count = next;
                msg.updated_at = now;
                count += 1;
            }
            Ok(count)
        }

