    pub(crate) fn test_state_with_store(
        health_ok: bool,
    ) -> Result<(AppState, Arc<FakeStore>), Box<dyn Error>> {
        use coder_connectivity::tailnet::{DerpTrafficTracker, InMemoryCoordinator};

        let store = Arc::new(FakeStore::new(health_ok));
        let store_trait: Arc<dyn AppStore> = store.clone();
        let audit: Arc<dyn AuditSink> = Arc::new(MemoryAuditSink::default());
        let pubsub: Arc<dyn coder_core::pubsub::PubSub> =
            Arc::new(coder_core::pubsub::InMemoryPubSub::new());
        let agent_provider: Arc<dyn coder_connectivity::agents::AgentProvider> =
            Arc::new(coder_connectivity::agents::InMemoryAgentProvider::new());
        let coordinator = InMemoryCoordinator::new(Default::default());
        let derp_tracker = DerpTrafficTracker::new();
        let derp_server = coder_connectivity::derp::DerpServer::new(
            coder_connectivity::derp::NodeKey::new([0u8; 32]),
        );

        Ok((
            AppState::new(
                test_config()?,
                BuildMetadata::default(),
                Uuid::nil(),
                store_trait,
                audit,
                pubsub,
                agent_provider,
                coordinator,
                derp_tracker,
                derp_server,
                None,
                coder_telemetry::TelemetryReporter::disabled(Uuid::nil()),
                std::sync::Arc::new(coder_license::EntitlementSet::new()),
                None,
            )?,
            store,
        ))
    }

    pub(crate) fn test_state(health_ok: bool) -> Result<AppState, Box<dyn Error>> {
        test_state_with_store(health_ok).map(|(state, _)| state)
    }

    fn request(method: Method, uri: &str) -> Result<Request<Body>, http::Error> {
        Request::builder()
            .method(method)
            .uri(uri)
            .body(Body::empty())
    }

    fn json_request<T: Serialize>(
        method: Method,
        uri: &str,
        payload: &T,
    ) -> Result<Request<Body>, Box<dyn Error>> {
        let body = serde_json::to_vec(payload)?;
        let request = Request::builder()
            .method(method)
            .uri(uri)
            .header(CONTENT_TYPE, "application/json")
            .body(Body::from(body))?;
        Ok(request)
    }

    pub(crate) fn authenticated_request(
        method: Method,
        uri: &str,
        session_token: &str,
    ) -> Result<Request<Body>, http::Error> {
        Request::builder()
            .method(method)
            .uri(uri)
            .header(SESSION_TOKEN_HEADER, session_token)
            .body(Body::empty())
    }

    pub(crate) fn authenticated_json_request<T: Serialize>(
        method: Method,
        uri: &str,
        session_token: &str,
        payload: &T,
    ) -> Result<Request<Body>, Box<dyn Error>> {
        let body = serde_json::to_vec(payload)?;
        let request = Request::builder()
            .method(method)
            .uri(uri)
            .header(CONTENT_TYPE, "application/json")
            .header(SESSION_TOKEN_HEADER, session_token)
            .body(Body::from(body))?;
        Ok(request)
    }

    fn request_with_cookies(
        method: Method,
        uri: &str,
        cookies: &[(&str, &str)],
    ) -> Result<Request<Body>, http::Error> {
        let cookie_header = cookies
            .iter()
            .map(|(name, value)| format!("{name}={value}"))
            .collect::<Vec<_>>()
            .join("; ");
        Request::builder()
            .method(method)
            .uri(uri)
            .header(http::header::COOKIE, cookie_header)
            .body(Body::empty())
    }

    pub(crate) async fn call(
        app: Router,
        request: Request<Body>,
    ) -> Result<Response<Body>, Box<dyn Error>> {
        let response = match app.oneshot(request).await {
            Ok(response) => response,
            Err(never) => match never {},
        };

        Ok(response)
    }

    pub(crate) async fn response_json(response: Response<Body>) -> Result<Value, Box<dyn Error>> {
        let bytes = to_bytes(response.into_body(), usize::MAX).await?;
        Ok(serde_json::from_slice(&bytes)?)
    }

    pub(crate) async fn create_and_login(app: &Router) -> Result<String, Box<dyn Error>> {
        let create_response = call(
            app.clone(),
            json_request(
                Method::POST,
                "/api/v2/users/first",
                &CreateFirstUserRequest {
                    email: "owner@example.com".to_owned(),
                    username: "owner".to_owned(),
                    name: "Owner".to_owned(),
                    password: "Password123".to_owned(),
                    ..Default::default()
                },
            )?,
        )
        .await?;
        assert_eq!(create_response.status(), StatusCode::CREATED);

        let login_response = call(
            app.clone(),
            json_request(
                Method::POST,
                "/api/v2/users/login",
                &LoginWithPasswordRequest {
                    email: "owner@example.com".to_owned(),
                    password: "Password123".to_owned(),
                },
            )?,
        )
        .await?;
        assert_eq!(login_response.status(), StatusCode::CREATED);
        let login_body = response_json(login_response).await?;
        Ok(login_body
            .get("session_token")
            .and_then(Value::as_str)
            .ok_or("missing session token")?
            .to_owned())
    }

    async fn spawn_test_server(
        router: Router,
    ) -> Result<(Url, tokio::task::JoinHandle<()>), Box<dyn Error>> {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await?;
        let address = listener.local_addr()?;
        let handle = tokio::spawn(async move {
            let _ = axum::serve(listener, router.into_make_service()).await;
        });
        Ok((Url::parse(&format!("http://{address}"))?, handle))
    }

    async fn first_organization_id(
        app: &Router,
        session_token: &str,
    ) -> Result<Uuid, Box<dyn Error>> {
        let response = call(
            app.clone(),
            authenticated_request(Method::GET, "/api/v2/organizations", session_token)?,
        )
        .await?;
        assert_eq!(response.status(), StatusCode::OK);
        let body = response_json(response).await?;
        let org_id = body
            .as_array()
            .and_then(|organizations| organizations.first())
            .and_then(|organization| organization.get("id"))
            .and_then(Value::as_str)
            .ok_or("missing organization id")?;
        Ok(Uuid::parse_str(org_id)?)
    }

