    #[tokio::test]
    async fn post_custom_notification_validates_content() -> Result<(), Box<dyn Error>> {
        let app = build_router(test_state(true)?, None);
        let session_token = create_and_login(&app).await?;

        // Missing content field
        let payload = coder_core::CustomNotificationRequest { content: None };
        let resp = call(
            app.clone(),
            authenticated_json_request(
                Method::POST,
                "/api/v2/notifications/custom",
                &session_token,
                &payload,
            )?,
        )
        .await?;
        assert_eq!(resp.status(), StatusCode::BAD_REQUEST);

        // Empty title
        let payload = coder_core::CustomNotificationRequest {
            content: Some(coder_core::CustomNotificationContent {
                title: "  ".to_string(),
                message: "Hello".to_string(),
            }),
        };
        let resp = call(
            app.clone(),
            authenticated_json_request(
                Method::POST,
                "/api/v2/notifications/custom",
                &session_token,
                &payload,
            )?,
        )
        .await?;
        assert_eq!(resp.status(), StatusCode::BAD_REQUEST);

        // Title too long
        let payload = coder_core::CustomNotificationRequest {
            content: Some(coder_core::CustomNotificationContent {
                title: "a".repeat(121),
                message: "Hello".to_string(),
            }),
        };
        let resp = call(
            app.clone(),
            authenticated_json_request(
                Method::POST,
                "/api/v2/notifications/custom",
                &session_token,
                &payload,
            )?,
        )
        .await?;
        assert_eq!(resp.status(), StatusCode::BAD_REQUEST);

        // Valid request returns 204
        let payload = coder_core::CustomNotificationRequest {
            content: Some(coder_core::CustomNotificationContent {
                title: "Test".to_string(),
                message: "Test message".to_string(),
            }),
        };
        let resp = call(
            app,
            authenticated_json_request(
                Method::POST,
                "/api/v2/notifications/custom",
                &session_token,
                &payload,
            )?,
        )
        .await?;
        assert_eq!(resp.status(), StatusCode::NO_CONTENT);
        Ok(())
    }

