    /// Helper: create a connected workspace agent row.
    fn make_connected_agent(agent_id: Uuid) -> WorkspaceAgentRow {
        let now = OffsetDateTime::now_utc();
        WorkspaceAgentRow {
            id: agent_id,
            parent_id: None,
            created_at: now,
            updated_at: now,
            name: "test-agent".to_owned(),
            first_connected_at: Some(now),
            last_connected_at: Some(now),
            disconnected_at: None,
            resource_id: Uuid::new_v4(),
            auth_token: Uuid::new_v4(),
            auth_instance_id: None,
            architecture: "amd64".to_owned(),
            environment_variables: None,
            operating_system: "linux".to_owned(),
            directory: "/home/coder".to_owned(),
            expanded_directory: "/home/coder".to_owned(),
            version: "v2.19.0".to_owned(),
            api_version: "1.0".to_owned(),
            connection_timeout_seconds: 120,
            troubleshooting_url: String::new(),
            motd_file: String::new(),
            lifecycle_state: "ready".to_owned(),
            logs_length: 0,
            logs_overflowed: false,
            started_at: Some(now),
            ready_at: Some(now),
            subsystems: Vec::new(),
            display_apps: Vec::new(),
            display_order: 0,
            api_key_scope: "all".to_owned(),
        }
    }

    /// Helper: insert a connected agent AND the full workspace chain (resource
    /// → build → workspace) so that `authorize_agent_workspace` /
    /// `find_workspace_by_agent_id` succeeds.
    fn insert_agent_with_workspace(
        store: &FakeStore,
        agent_id: Uuid,
        owner_id: Uuid,
    ) -> Result<(), StorageError> {
        let agent = make_connected_agent(agent_id);
        let resource_id = agent.resource_id;
        store.insert_agent(agent)?;

        let job_id = Uuid::new_v4();
        let build_id = Uuid::new_v4();
        let workspace_id = Uuid::new_v4();
        let now = OffsetDateTime::now_utc();

        let resource = WorkspaceResourceRecord {
            id: resource_id,
            created_at: now,
            job_id,
            transition: "start".to_owned(),
            resource_type: "docker_container".to_owned(),
            name: "main".to_owned(),
            hide: false,
            icon: String::new(),
            daily_cost: 0,
        };
        store
            .workspace_resources
            .lock()
            .map_err(|e| StorageError::unavailable(e.to_string()))?
            .entry(job_id)
            .or_default()
            .push(resource);

        let build = WorkspaceBuildRecord {
            id: build_id,
            created_at: now,
            updated_at: now,
            workspace_id,
            build_number: 1,
            transition: "start".to_owned(),
            job_id,
            template_version_id: Uuid::new_v4(),
            initiator_id: owner_id,
            provisioner_state: None,
            deadline: None,
            max_deadline: None,
            reason: "initiator".to_owned(),
            daily_cost: 0,
        };
        store
            .workspace_builds
            .lock()
            .map_err(|e| StorageError::unavailable(e.to_string()))?
            .insert(build_id, build);

        let workspace = WorkspaceRecord {
            id: workspace_id,
            created_at: now,
            updated_at: now,
            owner_id,
            organization_id: Uuid::from_u128(2),
            template_id: Uuid::new_v4(),
            deleted: false,
            name: "test-workspace".to_owned(),
            autostart_schedule: None,
            ttl_ns: None,
            last_used_at: now,
            dormant_at: None,
            deleting_at: None,
            automatic_updates: "never".to_owned(),
            favorite: false,
            next_start_at: None,
        };
        store.insert_workspace(workspace)?;
        Ok(())
    }

    /// Helper: create a disconnected workspace agent row.
    fn make_disconnected_agent(agent_id: Uuid) -> WorkspaceAgentRow {
        let now = OffsetDateTime::now_utc();
        let earlier = now - Duration::from_secs(300);
        WorkspaceAgentRow {
            id: agent_id,
            parent_id: None,
            created_at: earlier,
            updated_at: now,
            name: "disconnected-agent".to_owned(),
            first_connected_at: Some(earlier),
            last_connected_at: Some(earlier),
            disconnected_at: Some(now),
            resource_id: Uuid::new_v4(),
            auth_token: Uuid::new_v4(),
            auth_instance_id: None,
            architecture: "amd64".to_owned(),
            environment_variables: None,
            operating_system: "linux".to_owned(),
            directory: "/home/coder".to_owned(),
            expanded_directory: "/home/coder".to_owned(),
            version: "v2.19.0".to_owned(),
            api_version: "1.0".to_owned(),
            connection_timeout_seconds: 120,
            troubleshooting_url: String::new(),
            motd_file: String::new(),
            lifecycle_state: "ready".to_owned(),
            logs_length: 0,
            logs_overflowed: false,
            started_at: Some(earlier),
            ready_at: Some(earlier),
            subsystems: Vec::new(),
            display_apps: Vec::new(),
            display_order: 0,
            api_key_scope: "all".to_owned(),
        }
    }

