    #[tokio::test]
    async fn get_workspace_agent_watch_metadata_returns_metadata() -> Result<(), Box<dyn Error>> {
        let (state, store) = test_state_with_store(true)?;
        let app = build_router(state, None);
        let token = create_and_login(&app).await?;

        let agent_id = Uuid::new_v4();
        insert_agent_with_workspace(&store, agent_id, Uuid::from_u128(1))?;

        store
            .workspace_agent_metadata
            .lock()
            .map_err(|e| e.to_string())?
            .push(WorkspaceAgentMetadataRow {
                workspace_agent_id: agent_id,
                display_name: "CPU Usage".to_owned(),
                key: "cpu".to_owned(),
                script: "cat /proc/loadavg".to_owned(),
                value: "0.5".to_owned(),
                error: String::new(),
                timeout: 5,
                interval: 10,
                collected_at: OffsetDateTime::now_utc(),
                display_order: 0,
            });

        let response = call(
            app,
            authenticated_request(
                Method::GET,
                &format!("/api/v2/workspaceagents/{agent_id}/watch-metadata"),
                &token,
            )?,
        )
        .await?;
        assert_eq!(response.status(), StatusCode::OK);
        // The watch-metadata handler returns SSE format (data: <json>\n\n),
        // not plain JSON. Extract the JSON payload from the SSE data lines.
        let bytes = to_bytes(response.into_body(), usize::MAX).await?;
        let sse_text = String::from_utf8(bytes.to_vec())?;
        let json_str: String = sse_text
            .lines()
            .filter_map(|line| line.strip_prefix("data: "))
            .collect::<Vec<_>>()
            .join("");
        let metadata: Vec<Value> = serde_json::from_str(&json_str)?;
        assert_eq!(metadata.len(), 1);
        assert_eq!(metadata[0].get("key").and_then(Value::as_str), Some("cpu"));
        assert_eq!(
            metadata[0].get("value").and_then(Value::as_str),
            Some("0.5")
        );
        Ok(())
    }

