    /// Helper: set up a FakeStore with an agent, workspace, and optionally an
    /// app. Returns (AppState, Arc<FakeStore>, agent_auth_token).
    fn setup_agent_test_state() -> Result<(AppState, Arc<FakeStore>, Uuid), Box<dyn Error>> {
        let (state, store) = test_state_with_store(true)?;
        let agent_token = Uuid::new_v4();
        let agent_id = Uuid::new_v4();
        let workspace_id = Uuid::new_v4();
        let resource_id = Uuid::new_v4();
        let job_id = Uuid::new_v4();
        let build_id = Uuid::new_v4();
        let owner_id = Uuid::from_u128(100);
        let now = OffsetDateTime::now_utc();

        let agent = WorkspaceAgentRow {
            id: agent_id,
            parent_id: None,
            created_at: now,
            updated_at: now,
            name: "test-agent".to_owned(),
            first_connected_at: None,
            last_connected_at: None,
            disconnected_at: None,
            resource_id,
            auth_token: agent_token,
            auth_instance_id: None,
            architecture: "amd64".to_owned(),
            environment_variables: None,
            operating_system: "linux".to_owned(),
            directory: "/home/coder".to_owned(),
            expanded_directory: "/home/coder".to_owned(),
            version: "2.0.0".to_owned(),
            api_version: "1.0".to_owned(),
            connection_timeout_seconds: 120,
            troubleshooting_url: String::new(),
            motd_file: String::new(),
            lifecycle_state: "ready".to_owned(),
            logs_length: 0,
            logs_overflowed: false,
            started_at: Some(now),
            ready_at: Some(now),
            subsystems: Vec::new(),
            display_apps: Vec::new(),
            display_order: 0,
            api_key_scope: "all".to_owned(),
        };
        store.insert_agent(agent)?;

        // Set up the full join chain: resource -> build -> workspace so that
        // find_workspace_by_agent_id can traverse agent -> resource -> build -> workspace.
        let resource = WorkspaceResourceRecord {
            id: resource_id,
            created_at: now,
            job_id,
            transition: "start".to_owned(),
            resource_type: "docker_container".to_owned(),
            name: "main".to_owned(),
            hide: false,
            icon: String::new(),
            daily_cost: 0,
        };
        store
            .workspace_resources
            .lock()
            .map_err(|e| StorageError::unavailable(e.to_string()))?
            .entry(job_id)
            .or_default()
            .push(resource);

        let build = WorkspaceBuildRecord {
            id: build_id,
            created_at: now,
            updated_at: now,
            workspace_id,
            build_number: 1,
            transition: "start".to_owned(),
            job_id,
            template_version_id: Uuid::new_v4(),
            initiator_id: owner_id,
            provisioner_state: None,
            deadline: None,
            max_deadline: None,
            reason: "initiator".to_owned(),
            daily_cost: 0,
        };
        store
            .workspace_builds
            .lock()
            .map_err(|e| StorageError::unavailable(e.to_string()))?
            .insert(build_id, build);

        let workspace = WorkspaceRecord {
            id: workspace_id,
            created_at: now,
            updated_at: now,
            owner_id,
            organization_id: Uuid::from_u128(2),
            template_id: Uuid::new_v4(),
            deleted: false,
            name: "test-workspace".to_owned(),
            autostart_schedule: None,
            ttl_ns: None,
            last_used_at: now,
            dormant_at: None,
            deleting_at: None,
            automatic_updates: "never".to_owned(),
            favorite: false,
            next_start_at: None,
        };
        store.insert_workspace(workspace)?;

        Ok((state, store, agent_token))
    }

    /// Helper: create an authenticated agent request using the agent token.
    fn agent_request(
        method: Method,
        uri: &str,
        agent_token: Uuid,
    ) -> Result<Request<Body>, http::Error> {
        Request::builder()
            .method(method)
            .uri(uri)
            .header(SESSION_TOKEN_HEADER, agent_token.to_string())
            .body(Body::empty())
    }

    fn agent_json_request<T: Serialize>(
        method: Method,
        uri: &str,
        agent_token: Uuid,
        payload: &T,
    ) -> Result<Request<Body>, Box<dyn Error>> {
        let body = serde_json::to_vec(payload)?;
        let req = Request::builder()
            .method(method)
            .uri(uri)
            .header(CONTENT_TYPE, "application/json")
            .header(SESSION_TOKEN_HEADER, agent_token.to_string())
            .body(Body::from(body))?;
        Ok(req)
    }

